import {createAgentAPI,searchAssets,MODULES} from './agent-api.js';
import{WIDTH,HEIGHT,uid,clone,node,edge,escapeXML as esc,validateScene,emptyScene,defs,nodeMarkup,edgeMarkup,credits,exportSVG,exportDrawio,template}from'./core.js';
import{sanitizeSVG}from'./svg-safety.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#canvas'),assets=new Map(),history=[],future=[];let courseModule='course'; let scene=emptyScene(),selection=null,tool='select',connectFrom=null,category='all',query='',zoom=1,drag=null,toastTimer,loading=true;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function checkpoint(){history.push(clone(scene));if(history.length>60)history.shift();future.length=0;}
function persist(){scene.title=$('#project-title').value.trim().slice(0,300)||'未命名图稿';try{localStorage.setItem('biocanvas-v1',JSON.stringify(scene));$('#save-status').textContent='已保存在此浏览器';}catch{$('#save-status').textContent='请下载项目备份';}}
function commit(){persist();render();}
function selected(){return scene.nodes.find(n=>n.id===selection)||scene.edges.find(e=>e.id===selection);}
function choose(id){selection=id;render();}
function render(){canvas.innerHTML=defs+scene.edges.map(e=>edgeMarkup(e,scene.nodes,true)).join('')+scene.nodes.map(n=>nodeMarkup(n,assets)).join('');
 const n=scene.nodes.find(n=>n.id===selection);if(n)canvas.insertAdjacentHTML('beforeend',`<g pointer-events="none" transform="translate(${n.x} ${n.y}) rotate(${n.rotation} ${n.w/2} ${n.h/2})"><rect x="-8" y="-8" width="${n.w+16}" height="${n.h+16}" fill="none" stroke="#88a873" stroke-width="1.4" stroke-dasharray="5 3"/><rect class="resize-handle" data-resize="${esc(n.id)}" x="${n.w+3}" y="${n.h+3}" width="10" height="10" rx="2" fill="white" stroke="#729a5e" pointer-events="all"/></g>`);
 const e=scene.edges.find(e=>e.id===selection);if(e)canvas.querySelector(`[data-id="${CSS.escape(e.id)}"] path:last-of-type`)?.setAttribute('stroke-width','3.5');
 $('#undo').disabled=!history.length;$('#redo').disabled=!future.length;renderProperties();renderLayers();}
function renderProperties(){const n=selected();const box=$('#selection-properties');if(!n){box.innerHTML='<div class="empty-properties"><b>让研究过程一目了然</b><p>选择画布上的元素，编辑文字、大小和样式。也可以从左侧素材库开始。</p></div><label class="property-label">画布尺寸</label><div class="props-grid"><input value="1000 px" readonly aria-label="画布宽度"><input value="650 px" readonly aria-label="画布高度"></div><label class="property-label">背景</label><div class="color-row"><span class="swatch" style="background:white"></span><span class="muted" style="margin:0">白色 · 适合论文与报告</span></div>';return;}
 const a=n.assetId?assets.get(n.assetId):null;box.innerHTML=`<h3 class="prop-name">${esc(a?.label||(n.from?'连接线':n.type==='text'?'文本':'步骤框'))}</h3><label class="property-label" for="prop-label">${n.from?'连接线标注':'文字与标注'}</label><textarea id="prop-label" class="prop-text">${esc(n.label)}</textarea>${n.from?'':`<div class="props-grid">${[['x','X 位置'],['y','Y 位置'],['w','宽度'],['h','高度'],['fontSize','字号'],['rotation','旋转 °']].map(([key,label])=>`<label><span class="property-label">${label}</span><input type="number" data-prop="${key}" value="${Math.round(n[key])}" ${['w','h','fontSize'].includes(key)?'min="1"':''}></label>`).join('')}</div>`}<label class="property-label">${n.type==='asset'?'标注颜色（固定深灰）':'颜色'}</label>${n.type==='asset'?'':`<div class="color-row">${['#527d63','#819cba','#b89564','#a394b7','#3c5143'].map(c=>`<button class="swatch" data-color="${c}" style="background:${c}" aria-label="颜色 ${c}"></button>`).join('')}<input class="color-input" id="prop-color" type="color" value="${n.color}" aria-label="自定义颜色"></div>`}<div class="prop-actions">${n.from?'':'<button id="duplicate">复制</button><button id="bring-front">置顶</button>'}<button id="delete-selected">删除</button></div>${a?`<p class="credit-note">素材：${esc(a.name)}<br>作者：${esc(a.author)}<br>许可：${esc(a.license)} ${a.source?.startsWith('https://')?`· <a href="${esc(a.source)}" target="_blank" rel="noopener">来源 ↗</a>`:''}</p>`:''}`;
 $('#prop-label').onchange=e=>{checkpoint();n.label=e.target.value;commit();};$$('[data-prop]').forEach(input=>input.onchange=()=>{const k=input.dataset.prop;let v=Number(input.value);if(!Number.isFinite(v))return;checkpoint();n[k]=['w','h'].includes(k)?Math.max(10,Math.min(v,1500)):k==='fontSize'?Math.max(1,Math.min(v,200)):Math.max(-2000,Math.min(v,2000));commit();});$$('[data-color]').forEach(b=>b.onclick=()=>{checkpoint();n.color=b.dataset.color;commit();});if($('#prop-color'))$('#prop-color').onchange=e=>{checkpoint();n.color=e.target.value;commit();};if($('#duplicate'))$('#duplicate').onclick=duplicate;if($('#bring-front'))$('#bring-front').onclick=()=>{checkpoint();scene.nodes=scene.nodes.filter(a=>a.id!==n.id);scene.nodes.push(n);commit();};$('#delete-selected').onclick=removeSelected;}
function renderLayers(){$('#layer-count').textContent=scene.nodes.length;$('#layers').innerHTML=[...scene.nodes].reverse().map(n=>`<button class="layer-item ${selection===n.id?'active':''}" data-layer="${esc(n.id)}">${n.type==='asset'&&assets.get(n.assetId)?`<img src="${esc(assets.get(n.assetId).thumb)}" alt="">`:`<b>${n.type==='text'?'T':'▢'}</b>`}<span>${esc(n.label.split('\n')[0]||assets.get(n.assetId)?.label||'未命名')}</span></button>`).join('');$$('[data-layer]').forEach(b=>b.onclick=()=>choose(b.dataset.layer));}
function renderAssets(){const matches=new Set(searchAssets([...assets.values()],{query,module:courseModule==='course'?'':courseModule,limit:200}).items.map(a=>a.id));const filtered=[...assets.values()].filter(a=>matches.has(a.id)&&(category==='all'||a.category===category)&&(courseModule!=='course'||a.modules?.length));$('#asset-count').textContent=assets.size;$('#asset-grid').innerHTML=filtered.length?filtered.map(a=>`<button class="asset-card" data-asset="${esc(a.id)}" draggable="true" title="${esc(a.label+' · '+a.author+' · '+a.license)}"><img loading="lazy" src="${esc(a.thumb)}" alt=""><span>${esc(a.label)}</span></button>`).join(''):'<p class="muted" style="grid-column:1/-1">没有找到素材。试试英文名称，或导入自己的 SVG。</p>';$$('[data-asset]').forEach(b=>{b.onclick=()=>addAsset(b.dataset.asset).catch(e=>toast(e.message));b.ondragstart=e=>{e.dataTransfer.setData('application/x-biocanvas-asset',b.dataset.asset);e.dataTransfer.effectAllowed='copy';};});}
async function addAsset(id,p={x:450,y:255}){if(!assets.has(id))return;await ensureAsset(id);checkpoint();const a=assets.get(id),n=node('asset',{assetId:id,x:p.x-50,y:p.y-50,w:100,h:100,label:a.label});scene.nodes.push(n);selection=n.id;commit();}
function setTool(value){tool=value;connectFrom=null;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('#mode-hint').textContent=tool==='connect'?'依次点击两个元素，添加有向连线':'拖动元素调整布局 · 点击素材添加';canvas.style.cursor=tool==='connect'?'crosshair':'default';}
function point(e){const p=canvas.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(canvas.getScreenCTM().inverse());}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0||loading)return;const handle=e.target.closest('[data-resize]'),target=e.target.closest('[data-id]'),id=handle?.dataset.resize||target?.dataset.id;const n=scene.nodes.find(n=>n.id===id);if(tool==='connect'&&n){if(!connectFrom){connectFrom=n.id;choose(n.id);toast('已选择起点，请点击终点');}else if(connectFrom!==n.id){checkpoint();scene.edges.push(edge(connectFrom,n.id));connectFrom=null;commit();toast('连线已添加');}return;}selection=id||null;render();if(n){checkpoint();drag={id:n.id,start:point(e),x:n.x,y:n.y,w:n.w,h:n.h,resize:!!handle};canvas.setPointerCapture(e.pointerId);}});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=point(e),n=scene.nodes.find(n=>n.id===drag.id);let dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(drag.resize){const r=n.rotation*Math.PI/180,rx=dx*Math.cos(r)+dy*Math.sin(r),ry=-dx*Math.sin(r)+dy*Math.cos(r);n.w=Math.max(20,drag.w+rx);n.h=Math.max(20,drag.h+ry);}else{n.x=Math.round(Math.max(-n.w+20,Math.min(WIDTH-20,drag.x+dx)));n.y=Math.round(Math.max(-n.h+20,Math.min(HEIGHT-20,drag.y+dy)));}render();});
function endDrag(){if(drag){drag=null;commit();}}canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);
canvas.addEventListener('dblclick',e=>{const n=scene.nodes.find(n=>n.id===e.target.closest('[data-id]')?.dataset.id);if(!n)return;const value=prompt('编辑元素文字（详细换行可使用右侧属性面板）',n.label);if(value!==null){checkpoint();n.label=value;commit();}});
canvas.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';});canvas.addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('application/x-biocanvas-asset');if(id)addAsset(id,point(e)).catch(err=>toast(err.message));});
function addNode(type){checkpoint();const n=node(type,{label:type==='text'?'双击编辑文字':'新的步骤',w:type==='text'?220:180,h:type==='text'?35:76,fontSize:18});scene.nodes.push(n);selection=n.id;setTool('select');commit();}
function duplicate(){const n=scene.nodes.find(n=>n.id===selection);if(!n)return;checkpoint();const copy={...clone(n),id:uid(),x:n.x+22,y:n.y+22};scene.nodes.push(copy);selection=copy.id;commit();}
function removeSelected(){if(!selection)return;checkpoint();scene.nodes=scene.nodes.filter(n=>n.id!==selection);scene.edges=scene.edges.filter(e=>e.id!==selection&&e.from!==selection&&e.to!==selection);selection=null;commit();}
function undo(){if(!history.length)return;future.push(clone(scene));scene=history.pop();selection=null;$('#project-title').value=scene.title;commit();}
function redo(){if(!future.length)return;history.push(clone(scene));scene=future.pop();selection=null;$('#project-title').value=scene.title;commit();}
function setZoom(v){zoom=Math.max(.2,Math.min(2,v));$('#paper-wrap').style.width=WIDTH*zoom+'px';$('#paper-wrap').style.height=HEIGHT*zoom+'px';$('#zoom-label').textContent=Math.round(zoom*100)+'%';}
function fit(){const sc=$('#canvas-scroll');setZoom(Math.min((sc.clientWidth-65)/WIDTH,(sc.clientHeight-40)/HEIGHT,1));}
function download(content,name,type){const blob=content instanceof Blob?content:new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}
function filename(){return(scene.title||'BioCanvas').replace(/[\\/:*?"<>|]/g,'-');}
function projectJSON(){const copy=clone(scene);const used=new Set(copy.nodes.map(n=>n.assetId));copy.customAssets=copy.customAssets.filter(a=>used.has(a.id));copy.attributions=credits(scene,assets);return JSON.stringify(copy,null,2);}
async function exportAs(format){try{persist();await ensureSceneAssets(scene);if(format==='json')download(projectJSON(),filename()+'.biocanvas','application/json');if(format==='svg')download(exportSVG(scene,assets),filename()+'.svg','image/svg+xml');if(format==='drawio')download(exportDrawio(scene,assets),filename()+'.drawio','application/xml');if(format==='png'){const blob=new Blob([exportSVG(scene,assets)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const image=new Image();image.src=url;await image.decode();const c=document.createElement('canvas');c.width=2000;c.height=1300;const ctx=c.getContext('2d');ctx.drawImage(image,0,0,c.width,c.height);const png=await new Promise(r=>c.toBlob(r,'image/png'));if(!png)throw Error('无法创建 PNG');download(png,filename()+'.png','image/png');}finally{URL.revokeObjectURL(url);}}toast('已导出，请查看浏览器下载');}catch(e){toast('导出失败：'+e.message);}}
function registerAsset(meta,raw){const sanitized=sanitizeSVG(raw,'asset-'+meta.id.replace(/[^a-zA-Z0-9_-]/g,'_'));const a={...meta,...sanitized};a.thumb='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(a.svg);assets.set(a.id,a);return a;}
function loadCustom(list=[]){for(const a of list)registerAsset({...a,category:'Custom',source:a.source?.startsWith('https://')?a.source:'',license:a.license||'用户提供，待核实',author:a.author||'用户导入',name:a.name||a.label||'Custom SVG'},a.svg);}
$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#add-text').onclick=()=>addNode('text');$('#add-box').onclick=()=>addNode('box');$('#undo').onclick=undo;$('#redo').onclick=redo;$('#zoom-fit').onclick=fit;$('#zoom-in').onclick=()=>setZoom(zoom+.1);$('#zoom-out').onclick=()=>setZoom(zoom-.1);$('#asset-search').oninput=e=>{query=e.target.value.trim().toLowerCase();renderAssets();};$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;$$('[data-category]').forEach(btn=>btn.classList.toggle('active',btn===b));renderAssets();});$$('[data-panel]').forEach(b=>b.onclick=()=>{$$('[data-panel]').forEach(btn=>btn.classList.toggle('active',btn===b));['assets','templates','integrations'].forEach(id=>$('#panel-'+id).hidden=id!==b.dataset.panel);});
$('#project-title').onchange=()=>{checkpoint();commit();};$('#export-open').onclick=()=>$('#export-dialog').showModal();$('#help-open').onclick=()=>$('#help-dialog').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d&&((e.clientX<d.getBoundingClientRect().left)||(e.clientX>d.getBoundingClientRect().right)||(e.clientY<d.getBoundingClientRect().top)||(e.clientY>d.getBoundingClientRect().bottom)))d.close();}));$$('[data-export]').forEach(b=>b.onclick=()=>exportAs(b.dataset.export));$('#save-project').onclick=()=>exportAs('json');$('#drawio-direct').onclick=()=>exportAs('drawio');$('#svg-direct').onclick=()=>exportAs('svg');$('#credits-export').onclick=()=>download(JSON.stringify(credits(scene,assets),null,2),filename()+'-素材来源.json','application/json');
$$('[data-template]').forEach(b=>b.onclick=async()=>{try{const next=template(b.dataset.template);await ensureSceneAssets(next);checkpoint();scene=next;selection=null;$('#project-title').value=scene.title;commit();toast('已加载模板，可撤销恢复之前的图稿');}catch(e){toast(e.message);}});
$('#generate-flow').onclick=()=>{const steps=$('#steps-input').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!steps.length){toast('请先输入步骤，每行一步');return;}if(steps.length>12){toast('每张图最多自动排列 12 个步骤');return;}checkpoint();scene=emptyScene('实验步骤流程');scene.nodes.push(node('text',{x:65,y:45,w:860,h:36,label:'Experimental workflow',fontSize:28,color:'#344f3f'}));const cols=steps.length<=4?steps.length:3,rows=Math.ceil(steps.length/cols),w=Math.min(230,800/cols-20),rowH=430/rows;let prev;steps.forEach((label,i)=>{const row=Math.floor(i/cols),col=row%2?cols-1-i%cols:i%cols;const n=node('box',{x:70+col*(860/cols),y:155+row*rowH,w,h:Math.min(90,rowH-35),label:`${String(i+1).padStart(2,'0')}  ${label}`,fontSize:15});scene.nodes.push(n);if(prev)scene.edges.push(edge(prev.id,n.id));prev=n;});selection=null;$('#project-title').value=scene.title;commit();toast('已按输入步骤生成流程图');};
$('#open-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>12000000)throw Error('项目文件请保持在 12 MB 以内');const next=validateScene(JSON.parse(await f.text()));loadCustom(next.customAssets);const missing=next.nodes.filter(n=>n.type==='asset'&&!assets.has(n.assetId));if(missing.length)throw Error('项目包含当前版本不支持的素材');await ensureSceneAssets(next);checkpoint();scene=next;selection=null;$('#project-title').value=scene.title;commit();renderAssets();toast('项目已打开');}catch(err){toast('无法打开：'+err.message);}e.target.value='';};
$('#import-svg').onclick=()=>$('#svg-file').click();$('#svg-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('SVG 文件请保持在 2 MB 以内');const id='custom-'+uid();const a=registerAsset({id,name:f.name,label:f.name.replace(/\.svg$/i,''),category:'Custom',author:'用户导入',license:'用户提供，待核实',source:''},await f.text());checkpoint();scene.customAssets.push({id,name:a.name,label:a.label,svg:a.svg,license:a.license,author:a.author});scene.nodes.push(node('asset',{assetId:id,label:a.label}));selection=scene.nodes.at(-1).id;commit();renderAssets();toast('SVG 已导入。请确认你拥有素材使用权。');}catch(err){toast(err.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('dialog[open]'))return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if(mod&&key==='s'){e.preventDefault();exportAs('json');}else if(mod&&key==='d'){e.preventDefault();duplicate();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected();}else if(e.key==='Escape'){selection=null;setTool('select');render();}else if(key==='v')setTool('select');else if(key==='c')setTool('connect');else if(key==='t')addNode('text');else if(key==='/'){e.preventDefault();$('#asset-search').focus();}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){const n=scene.nodes.find(n=>n.id===selection);if(n){e.preventDefault();checkpoint();const step=e.shiftKey?10:1;n.x+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;n.y+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;commit();}}});
window.addEventListener('resize',fit);
const pendingAssets=new Map();
async function ensureAsset(id){
 const a=assets.get(id);if(!a)throw Error('未知素材：'+id);if(a.inner!==undefined)return a;
 if(!pendingAssets.has(id))pendingAssets.set(id,(async()=>{const r=await fetch(a.src);if(!r.ok)throw Error('素材无法加载：'+a.label);return registerAsset(a,await r.text());})().finally(()=>pendingAssets.delete(id)));
 return pendingAssets.get(id);
}
async function ensureSceneAssets(next){await Promise.all([...new Set(next.nodes.filter(n=>n.type==='asset').map(n=>n.assetId))].map(ensureAsset));return assets;}
const ai=createAgentAPI({read:()=>scene,catalog:()=>[...assets.values()],loadAssets:ensureSceneAssets,write:next=>{checkpoint();scene=next;selection=null;$('#project-title').value=scene.title;commit();}});
$('#course-module').innerHTML='<option value="course">BIO 251 · 本学期精选</option><option value="">全部素材</option>'+MODULES.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
$('#course-module').onchange=e=>{courseModule=e.target.value;renderAssets();};
$('#ai-request-open').onclick=()=>$('#ai-request-file').click();
$('#ai-request-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('请求文件请保持在 2 MB 以内');const result=await ai.request(JSON.parse(await f.text()));download(JSON.stringify(result,null,2),'biocanvas-ai-response.json','application/json');toast(result.ok?'AI 请求已完成；修改可撤销':result.error.message);}catch(error){toast(error.message);}e.target.value='';};
async function init(){
 const res=await fetch('assets/catalog.json');if(!res.ok)throw Error('素材清单无法读取');
 for(const a of await res.json())assets.set(a.id,{...a,thumb:a.src});
 let recovered=false;try{const saved=localStorage.getItem('biocanvas-v1');if(saved){const parsed=validateScene(JSON.parse(saved));loadCustom(parsed.customAssets);await ensureSceneAssets(parsed);scene=parsed;recovered=true;}}catch{toast('本地项目无法恢复，已载入示例');}
 if(!recovered)scene=template('transformation');await ensureSceneAssets(scene);
 $('#project-title').value=scene.title;loading=false;renderAssets();render();fit();
}
const ready=init();
window.bioCanvasAI=Object.freeze({...ai,ready});
ready.catch(e=>{loading=false;$('#asset-grid').textContent='素材暂时无法加载，请刷新重试。';toast(e.message);});
